  if(!r||r.key!==key||now-r.last>1000){ CRASH_RUN={key:key,t0:now,last:now,n:1}; return false; }
  r.last=now; r.n++;
  var dur=now-r.t0;
  return dur>=CRASH_LOOP_MS&&r.n>=dur/100;
}
